// 아티스트/멤버 이름으로 Google News 검색 주소와 캐시 키(오늘 날짜)를 만든다.
const q = $json.query || {};
// "세븐틴 (SEVENTEEN)" → "세븐틴"
const artist = String(q.artist || '세븐틴').replace(/\s*\(.*?\)\s*/g, '').trim().slice(0, 30);
const member = String(q.member || '').trim().slice(0, 30);
// 캐시 만료 기준일 (한국 시간)
const date = new Date(Date.now() + 9 * 3600 * 1000).toISOString().slice(0, 10);

const keyword = member ? `${artist} ${member}` : artist;
const rssUrl = 'https://news.google.com/rss/search?q='
  + encodeURIComponent(`${keyword} when:30d`)
  + '&hl=ko&gl=KR&ceid=KR:ko';

return [{ json: { date, artist, member, keyword, rssUrl } }];

// 캐시에 저장된 브리핑 JSON 문자열을 응답 형식으로 복원한다.
let briefing = {};
try {
  briefing = JSON.parse($json.news_data || '{}');
} catch (e) {
  briefing = {};
}
return [{ json: { ...briefing, cached: true } }];

// Google News RSS(XML)에서 최신 기사 목록을 뽑고 Gemini 요약 프롬프트를 만든다.
const ctx = $('Build News Query').first().json;
const xml = typeof $json.data === 'string' ? $json.data : '';

const decode = s => s
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .trim();
const pick = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return m ? decode(m[1]) : '';
};

const seen = new Set();
let articles = [];
for (const m of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
  const block = m[1];
  const source = pick(block, 'source');
  let title = pick(block, 'title');
  // "제목 - 언론사" 형식에서 언론사 꼬리 제거
  if (source && title.endsWith(` - ${source}`)) title = title.slice(0, -(source.length + 3));
  if (!title || seen.has(title)) continue;
  seen.add(title);
  const date = new Date(pick(block, 'pubDate'));
  articles.push({
    title,
    link: pick(block, 'link'),
    source,
    pubDate: isNaN(date) ? '' : date.toISOString().slice(0, 10),
  });
}
// Google News는 관련도 순이므로 최신순으로 다시 정렬
articles = articles.sort((a, b) => b.pubDate.localeCompare(a.pubDate)).slice(0, 8);

const prompt = `너는 K-POP 팬 앱의 뉴스 브리핑 에디터다.
아래는 "${ctx.keyword}" 관련 최근 30일 기사 제목 목록이다. 기사 본문은 없고 제목만 있다.

${articles.map((a, i) => `${i + 1}. [${a.pubDate}] ${a.title} (${a.source})`).join('\n')}

[규칙]
1. 반드시 위 기사 제목에 나온 사실만 사용한다. 제목에 없는 일정, 수치, 발언을 지어내지 않는다.
2. ${ctx.member || ctx.artist}와 직접 관련 없는 기사는 무시한다.
3. headline: 최근 활동을 대표하는 한 줄 (40자 이내)
4. summary: 최근 활동 흐름을 2~3문장으로 요약
5. activity_tag: 활동 성격 짧은 태그 (예: 컴백, 화보, 예능, 공연, 근황)
6. fan_cheer: 팬이 보낼 법한 짧은 응원 한마디
7. 아래 JSON만 출력한다.

{"activity_tag":"","headline":"","summary":"","fan_cheer":""}`;

return [{ json: { ...ctx, articles, prompt } }];

// Gemini 요약을 검증하고 근거 기사 링크를 붙인다.
// 기사가 없으면 headline을 비워 프론트가 기본 프로필 브리핑을 보여주게 한다.
const ctx = $('Parse Articles').first().json;
const articles = ctx.articles || [];

let parsed = null;
try {
  const parts = ($json.candidates && $json.candidates[0] && $json.candidates[0].content
    && $json.candidates[0].content.parts) || [];
  parsed = JSON.parse(parts.map(p => p.text || '').join('').replace(/```json|```/g, '').trim());
} catch (e) {
  parsed = null;
}

const clip = (v, n) => String(v || '').trim().slice(0, n);
let briefing;
if (articles.length === 0) {
  briefing = { activity_tag: '', headline: '', summary: '', fan_cheer: '', source: 'no-articles' };
} else if (parsed && parsed.headline && parsed.summary) {
  briefing = {
    activity_tag: clip(parsed.activity_tag, 12) || '최근 활동',
    headline: clip(parsed.headline, 60),
    summary: clip(parsed.summary, 300),
    fan_cheer: clip(parsed.fan_cheer, 80),
    source: 'n8n Gemini 분석',
  };
} else {
  // AI 실패 시 기사 제목으로 직접 구성
  briefing = {
    activity_tag: '최신 기사',
    headline: clip(articles[0].title, 60),
    summary: articles.slice(1, 3).map(a => a.title).join(' / ') || clip(articles[0].title, 300),
    fan_cheer: '',
    source: 'n8n 기사 헤드라인',
  };
}

return [{
  json: {
    ...briefing,
    member: ctx.member,
    articles: articles.slice(0, 3),
    searchedAt: new Date().toISOString(),
    cached: false,
  },
}];

// AI 요약이 성공한 결과만 캐시에 적재한다.
// 실패 결과를 저장하면 그날 하루 동안 대체 화면이 고정되므로 제외.
if ($json.source !== 'n8n Gemini 분석') return [];

const ctx = $('Build News Query').first().json;
const { cached, ...briefing } = $json;
return [{
  json: {
    date: ctx.date,
    artist: ctx.artist,
    member: ctx.member,
    news_data: JSON.stringify(briefing),
  },
}];
